parameters.jsCode:
const p = $json.body ?? $json;
const raw = String(p.ButtonPayload || p.ButtonText || p.Body || '').trim();
const normalized = raw.toUpperCase();
let decision = 'unrecognized';
if (normalized === 'ACCEPT' || normalized.includes('ACCEPT ASSIGNMENT')) decision = 'accepted';
if (normalized === 'DECLINE' || normalized.includes('DECLINE ASSIGNMENT')) decision = 'declined';
const workerPhone = String(p.From || '').replace(/^whatsapp:/i, '');
return [{ json: { decision, raw_reply: raw, worker_phone: workerPhone, inbound_message_sid: p.MessageSid || p.SmsMessageSid || '', received_at: new Date().toISOString() } }];

